    C public c;

    constructor(C _c) { c = _c; }

    // single public test function driving the contract and asserting the distinguishing property
    function run(address logger, address callerCandidate, address keepAddress) public {
        // Precondition: callerCandidate must not already be approved (if it is, pick a different input when invoking the test)
        // We observe approval status via the public getter approvedToLog
        require(c.approvedToLog(callerCandidate) == false);

        // Approve `logger` as an approved logger (must be performed by contract owner in real use; in tests the deployed C should have owner set appropriately)
        // We perform the state-changing call as a top-level statement. If the test harness cannot call setApprovedLogger due to onlyOwner restriction,
