pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    HelperCaller helper;

    function setUp() public {
        c = new C();
        helper = new HelperCaller();
    }

    // Fuzz parameters: an address to query and a boolean status to set in the mapping for that address.
    // We let the fuzzer pick both; the difference between reference and mutant manifests when a contract
    // (the helper) calls approvedToLog on behalf of a different address: reference uses the provided arg,
    // mutant uses tx.origin (the EOA we choose here), so behavior can differ.
    function testFuzz_property(address queried, bool status) public {
        // keep domain wide but avoid the zero address to be safe (mapping supports zero but it's fine to skip)
        vm.assume(queried != address(0));

        // Set mapping entry for the queried address: onlyOwner modifier applies in contract C, so we must
        // call setApprovedLogger as the owner. In C the owner is the contract deployer (c) private var _contractOwner
        // However setUp deployed C from this test contract, which is msg.sender here -> this test is owner.
        c.setApprovedLogger(queried, status);

        // Now we want to observe approvedToLog when called by a CONTRACT (helper) on behalf of `queried`.
        // The reference returns approvedLoggers[queried]; the mutant returns approvedLoggers[tx.origin].
        // We call helper.callApprovedToLog(c, queried). The tx.origin will be this EOA (address(this) in test),
        // while the callee argument is `queried`. For some choices where approvedLoggers[queried] != approvedLoggers[tx.origin]
        // the mutant will differ. We do not restrict that here; fuzzer will search.

        // Ensure the helper contract has some native balance so calls behave normally (not required for view, but safe)
        vm.deal(address(helper), 1 wei);

        // The helper will perform an external call into c.approvedToLog(queried) and return the bool it got.
        bool returnedFromCall = helper.callApprovedToLog(address(c), queried);

        // The reference contract MUST satisfy this universal property for all inputs: when a contract calls
        // approvedToLog(queried) it returns approvedLoggers[queried]. We assert that the observed return equals
        // the public getter approvedLoggers(queried) (auto-generated getter).
        // This holds for the reference implementation for every admissible input. The mutant that uses tx.origin
        // instead will fail for at least some fuzz inputs (where approvedLoggers[queried] != approvedLoggers[tx.origin]).
        assertTrue(returnedFromCall == c.approvedLoggers(queried));
    }
}

// Minimal helper contract that calls C.approvedToLog(address) as a contract (so tx.origin != address(this) when called from the test EOA)
contract HelperCaller {
    function callApprovedToLog(address caddr, address queried) external returns (bool) {
        // Call the public view function; use low-level call to ensure behaving as an external contract call
        (bool ok, bytes memory ret) = caddr.call(abi.encodeWithSignature("approvedToLog(address)", queried));
        require(ok, "call failed");
        return abi.decode(ret, (bool));
    }
}

